export const BODY: string = "\n<p>SVG ویکٹر فائل ہے، جو ریاضی سے بنتی ہے اور ہر سائز میں تیز رہتی ہے۔ PNG پکسلز سے بنتی ہے، جو ہر جگہ کھلتی ہے۔ SVG کو PNG میں بدلنا ویکٹر کو پکسلز میں بدلنا ہے۔</p>\n<p>یہ تبدیلی اس وقت ضروری ہے جب SVG کہیں نہ کھلے، جیسے پرانے سافٹ ویئر، ای میل یا سوشل میڈیا میں۔ PNG ہر جگہ کھلتا ہے، اس لیے وہ محفوظ انتخاب ہے۔</p>\n<p>یہ رہنما بتاتا ہے کہ ریسٹرائز کیا ہے، درست اسکیل کیسے چنیں، شفافیت کیسے بچتی ہے، اور فونٹ و لنک شدہ تصویروں کا کیا ہوتا ہے۔ تبدیل کرنے کے لیے <a href=\"/ur/svg-ko-png-mein-convert-karein/\">SVG ٹو PNG</a> استعمال کریں۔</p>\n<h2 id=\"what-is-svg\">SVG فائل کیا ہے؟</h2>\n<p>SVG ایک ویکٹر فارمیٹ ہے، جس میں تصویر لکیروں اور شکلوں کے حساب سے لکھی ہوتی ہے، پکسلز سے نہیں۔ اس لیے SVG کو جتنا بڑا کریں، وہ اتنا ہی تیز رہتا ہے۔</p>\n<p>SVG لوگو اور آئیکن کے لیے بنایا گیا تھا، کیونکہ وہ ہر سائز میں استعمال ہوتے ہیں۔ ایک SVG لوگو چھوٹے آئیکن اور بڑے بینر، دونوں میں تیز رہتا ہے۔</p>\n<p>SVG متن کی فائل ہے، اس لیے اسے ٹیکسٹ ایڈیٹر میں کھول کر پڑھا جا سکتا ہے۔ یہی اس کی طاقت اور کمزوری دونوں ہے۔</p>\n<h2 id=\"what-is-rasterizing\">ریسٹرائز کرنے کا کیا مطلب ہے؟</h2>\n<p>ریسٹرائز کرنا ویکٹر کو پکسلز میں بدلنا ہے۔ SVG کی لکیریں پکسلز کی جالی میں بدل جاتی ہیں، اور نتیجہ PNG بنتا ہے۔</p>\n<p>ریسٹرائز کرنے کے بعد تصویر کو بڑا کرنے پر وہ دھندلی ہو جاتی ہے، کیونکہ پکسلز طے ہو جاتے ہیں۔ اس لیے درست سائز پر ریسٹرائز کرنا ضروری ہے۔</p>\n<p>ریسٹرائز ایک طرفہ عمل ہے: PNG سے اصل SVG واپس نہیں بنتا۔ اصل SVG محفوظ رکھیں۔</p>\n<h2 id=\"choosing-scale\">درست اسکیل کیسے چنیں</h2>\n<p>اسکیل طے کرتا ہے کہ PNG کتنے پکسلز کا بنے گا۔ 24 پکسلز آئیکن کو 4 گنا اسکیل پر 96 پکسلز PNG بنتا ہے، جو تیز نظر آتا ہے۔</p>\n<p>اسکیل اتنا بڑا چنیں جتنا منزل کو چاہیے، اس سے زیادہ نہیں۔ بہت بڑا اسکیل فائل کو بہت بڑا کر دیتا ہے، بغیر کوئی فائدہ دیے۔</p>\n<p>ریٹینا اسکرین کے لیے 2 گنا اسکیل کافی ہے۔ پرنٹ کے لیے 4 گنا یا اس سے زیادہ چاہیے ہو سکتا ہے۔</p>\n<h2 id=\"transparency-preserved\">شفافیت محفوظ رہتی ہے</h2>\n<p>SVG کی شفافیت PNG میں بچتی ہے، اس لیے شفاف لوگو PNG میں بھی شفاف رہتا ہے۔ یہ لوگو کے لیے بہت اہم ہے۔</p>\n<p>شفافیت جانچنے کے لیے تبدیل شدہ PNG کو رنگین پس منظر پر دیکھیں۔ اگر لوگو کے گرد سفید ڈبہ نہ ہو تو شفافیت بچ گئی ہے۔</p>\n<p>شفافیت کے لیے PNG استعمال کریں، JPG نہیں۔ JPG شفافیت مٹا دیتا ہے۔</p>\n<h2 id=\"fonts-and-text\">SVG کے اندر فونٹ اور متن</h2>\n<p>SVG میں متن فونٹ سے لکھا ہوتا ہے، اور اگر وہ فونٹ آپ کے کمپیوٹر میں نہ ہو تو متن بدل جاتا ہے۔ تبدیلی سے پہلے فونٹ جانچیں۔</p>\n<p>محفوظ طریقہ یہ ہے کہ متن کو شکل میں بدل دیں، تاکہ وہ فونٹ پر منحصر نہ رہے۔ شکل میں بدلا ہوا متن ہر جگہ ایک جیسا نظر آتا ہے۔</p>\n<p>ویب فونٹ SVG میں کام کر سکتا ہے، مگر کنورٹر اسے نہیں پڑھ سکتا۔ فونٹ کا مسئلہ ہو تو متن کو شکل میں بدلیں۔</p>\n<h2 id=\"linked-images\">لنک شدہ تصویریں اور بیرونی فائلیں</h2>\n<p>SVG میں بیرونی تصویر لنک ہو سکتی ہے، جو SVG فائل کے باہر رہتی ہے۔ تبدیل کرتے وقت وہ تصویر غائب ہو سکتی ہے، کیونکہ کنورٹر اسے نہیں پاتا۔</p>\n<p>لنک شدہ تصویر کو SVG میں ایمبیڈ کریں، تاکہ وہ فائل کے اندر آ جائے۔ ایمبیڈ شدہ تصویر تبدیلی میں محفوظ رہتی ہے۔</p>\n<p>تبدیلی کے بعد PNG کو دیکھ کر جانچیں کہ سب تصویریں موجود ہیں۔ اگر کوئی غائب ہو تو اسے ایمبیڈ کریں۔</p>\n<h2 id=\"gradients-and-opacity\">گریڈینٹ، شفافیت اور اثرات</h2>\n<p>SVG کے گریڈینٹ اور شفافیت PNG میں محفوظ رہتے ہیں، مگر کچھ پیچیدہ اثرات بدل سکتے ہیں۔ فلٹر اور چمک جیسے اثرات ہر کنورٹر میں ایک جیسے نہیں بنتے۔</p>\n<p>پیچیدہ اثرات والی SVG کو تبدیل کرنے سے پہلے اس کا پیش منظر دیکھیں۔ اگر اثر بدل گیا ہو تو SVG کو سادہ کریں۔</p>\n<p>سادہ SVG ہمیشہ درست بدلتی ہے۔ پیچیدہ اثرات صرف اس وقت استعمال کریں جب وہ ضروری ہوں۔</p>\n<h2 id=\"batch-converting-icons\">آئیکن پیک کی بیچ تبدیلی</h2>\n<p>آئیکن پیک میں درجنوں SVG آئیکن ہوتے ہیں، جنہیں بیچ میں ایک ساتھ PNG میں بدلا جا سکتا ہے۔ یہ بہت وقت بچاتا ہے۔</p>\n<p>بیچ میں سب آئیکن پر ایک ہی اسکیل لگائیں، تاکہ سب یکساں ہوں۔ بیچ کا نتیجہ ZIP میں ملتا ہے۔</p>\n<p>بیچ بدلنے سے پہلے ایک آئیکن آزمائیں۔ اگر وہ صاف ہو تو پوری پیک بدلیں۔</p>\n<h2 id=\"when-to-use-png-instead\">PNG کب استعمال کریں، SVG کے بجائے</h2>\n<p>PNG اس وقت استعمال کریں جب SVG کہیں نہ کھلے، جیسے ای میل، پرانا سافٹ ویئر یا سوشل میڈیا۔ PNG ہر جگہ کھلتا ہے۔</p>\n<p>PNG اس وقت بھی استعمال کریں جب تصویر کو ایڈٹ کرنا ہو۔ زیادہ تر ایڈیٹر SVG نہیں کھولتے، مگر PNG کھولتے ہیں۔</p>\n<p>ویب کے لیے SVG بہتر ہے، کیونکہ وہ ہلکا اور تیز ہے۔ PNG صرف اس وقت چنیں جب SVG کام نہ کرے۔</p>\n<h2 id=\"colour-accuracy\">کیا تبدیلی رنگ بدلتی ہے؟</h2>\n<p>تبدیلی میں رنگ عام طور پر وہی رہتے ہیں، مگر رنگ پروفائل بدل سکتا ہے۔ نتیجہ کا رنگ اصل سے ملا کر دیکھیں۔</p>\n<p>اگر رنگ بدل جائیں تو SVG کا رنگ پروفائل جانچیں۔ کچھ SVG میں رنگ پروفائل نہیں ہوتا، اس لیے کنورٹر اندازہ لگاتا ہے۔</p>\n<p>رنگ کی درستگی کے لیے اصل SVG محفوظ رکھیں اور PNG کو صرف نقل کے طور پر استعمال کریں۔</p>\n<h2 id=\"file-sizes\">تبدیلی کے بعد فائل کے سائز</h2>\n<p>PNG فائل SVG سے بہت بڑی ہوتی ہے، کیونکہ SVG صرف حساب رکھتا ہے اور PNG ہر پکسل رکھتا ہے۔ سادہ لوگو کی SVG چند کلو بائٹ کی ہوتی ہے، PNG سینکڑوں کلو بائٹ کا ہو سکتا ہے۔</p>\n<p>فائل کا سائز اسکیل پر منحصر ہے: بڑا اسکیل بڑی فائل بناتا ہے۔ صرف اتنا بڑا اسکیل چنیں جتنا چاہیے۔</p>\n<p>اگر فائل بہت بڑی ہو تو اسے کمپریس کریں۔ PNG کو کمپریس کرنے سے معیار نہیں گرتا۔</p>\n<h2 id=\"common-problems\">عام مسائل اور ان کا حل</h2>\n<p>سب سے عام مسئلہ غائب فونٹ ہے، جس سے متن بدل جاتا ہے۔ حل یہ ہے کہ متن کو شکل میں بدلیں۔</p>\n<p>دوسرا مسئلہ غائب لنک شدہ تصویر ہے۔ حل یہ ہے کہ تصویر کو ایمبیڈ کریں۔</p>\n<p>تیسرا مسئلہ غلط اسکیل ہے، جس سے تصویر دھندلی ہو جاتی ہے۔ حل یہ ہے کہ اسکیل بڑھائیں اور دوبارہ تبدیل کریں۔</p>\n<h2 id=\"svg-logos-social-media\">سوشل میڈیا کے لیے SVG لوگو</h2>\n<p>سوشل میڈیا اکثر SVG نہیں لیتا، اس لیے لوگو کو PNG میں بدلنا پڑتا ہے۔ پروفائل تصویر کے لیے 500 پکسلز PNG کافی ہے۔</p>\n<p>سوشل لوگو کے لیے شفاف PNG استعمال کریں، تاکہ وہ ہر پس منظر پر درست لگے۔</p>\n<p>سوشل پلیٹ فارم کی سائز گائیڈ دیکھیں اور اسی سائز میں PNG بنائیں۔</p>\n<h2 id=\"svg-icons-apps\">ایپس کے لیے SVG آئیکن</h2>\n<p>ایپ آئیکن SVG میں بنتے ہیں، مگر ایپ اسٹور PNG مانگتا ہے۔ اسٹور کے لیے ہر سائز میں PNG بنائیں۔</p>\n<p>ایپ کے اندر استعمال ہونے والے آئیکن SVG میں رکھیں، تاکہ ایپ ہلکی رہے۔ اسٹور کے لیے PNG نقل بنائیں۔</p>\n<p>آئیکن کا سائز درست رکھیں: غلط سائز کا آئیکن مسترد ہو جاتا ہے۔</p>\n<h2 id=\"svg-for-print-materials\">پرنٹ مواد کے لیے SVG</h2>\n<p>پرنٹ کے لیے SVG بہتر ہے، کیونکہ وہ ہر سائز میں تیز رہتا ہے۔ لیکن کچھ پرنٹر SVG نہیں لیتے، اس لیے PNG نقل بھی رکھیں۔</p>\n<p>پرنٹ کے لیے PNG کا اسکیل بڑا رکھیں، تاکہ وہ 300 ڈی پی آئی پر تیز نکلے۔ چھوٹا PNG پرنٹ میں دھندلا ہو جاتا ہے۔</p>\n<p>پرنٹ سے پہلے PNG کو مکمل سائز میں دیکھیں۔ اگر وہ صاف لگے تو پرنٹ بھی صاف نکلے گا۔</p>\n<h2 id=\"svg-for-email-signatures\">ای میل دستخط کے لیے SVG</h2>\n<p>ای میل دستخط میں SVG اکثر نہیں کھلتا، اس لیے لوگو کو PNG میں بدلیں۔ دستخط کا لوگو چھوٹا ہوتا ہے، اس لیے فائل بھی چھوٹی رہتی ہے۔</p>\n<p>ای میل دستخط کے لیے شفاف PNG استعمال کریں، تاکہ لوگو ہر ای میل کلائنٹ میں درست لگے۔</p>\n<p>دستخط کا لوگو 200 پکسلز سے بڑا نہ رکھیں، ورنہ ای میل بھاری ہو جاتی ہے۔</p>\n<h2 id=\"svg-for-favicons\">فیویکن کے لیے SVG</h2>\n<p>فیویکن براؤزر ٹیب میں نظر آنے والا چھوٹا آئیکن ہے۔ جدید براؤزر SVG فیویکن لیتے ہیں، مگر پرانے PNG مانگتے ہیں۔</p>\n<p>فیویکن کے لیے دونوں رکھیں: SVG جدید کے لیے اور PNG پرانے کے لیے۔ PNG 32 پکسلز کا کافی ہے۔</p>\n<p>فیویکن سادہ ہونا چاہیے، کیونکہ وہ بہت چھوٹا دکھائی دیتا ہے۔ پیچیدہ لوگو فیویکن میں پہچانا نہیں جاتا۔ SVG اور PNG کا موازنہ <a href=\"/ur/blog/svg-vs-png-vector-raster/\">SVG بمقابلہ PNG</a> میں اور عملی مراحل <a href=\"/ur/blog/svg-ko-png-mein-kaise-convert-karein/\">SVG کو PNG میں کیسے بدلیں</a> میں دیکھیں۔</p>\n";

